#!/bin/bash
# HenWen 2.0 per-user SIP identities -- include wiring (one-time).
#
# HenWen renders every account that has a callsign into two generated files:
#   /etc/asterisk/custom/henwen-sip-users.conf            (PJSIP endpoint/auth/aor)
#   /etc/asterisk/custom/henwen-sip-users-dialplan.conf   (one context per account)
# and reloads PJSIP/the dialplan whenever they change. Asterisk reads them
# only once pjsip.conf and extensions.conf carry a #tryinclude for each --
# a one-time edit to files HenWen does not own, which is why it lives here
# and not in the app (same reasoning as tx-spike/apply.sh). '#tryinclude',
# not '#include': the generated files may not exist yet, and a missing
# '#include' target is a config parse error.
#
# Marker-guarded and safe to re-run. Backs up both files first; rollback.sh
# removes the lines again. Does NOT restart Asterisk: `module reload
# res_pjsip.so` and `dialplan reload` pick the includes up live and touch no
# call already in progress.
#
# Prerequisite: tx-spike/apply.sh has run. The per-user endpoints are WebRTC
# endpoints exactly like the shared henwen-tx one and need the same
# transport (henwen-ws), modules, STUN setting and Apache WSS proxy it
# installs; they only replace the *credential*, not the plumbing.
set -euo pipefail

MARKER="HenWen per-user SIP"
PJSIP_CONF="${PJSIP_CONF:-/etc/asterisk/pjsip.conf}"
EXTENSIONS_CONF="${EXTENSIONS_CONF:-/etc/asterisk/extensions.conf}"
CUSTOM_DIR="${CUSTOM_DIR:-/etc/asterisk/custom}"
# Keep these two lines byte-identical to SIP_USERS_INCLUDE_LINE /
# SIP_DIALPLAN_INCLUDE_LINE in app.py: sip_include_status() looks for exactly
# this text to report "wired".
PJSIP_LINE='#tryinclude "custom/henwen-sip-users.conf"'
DIALPLAN_LINE='#tryinclude "custom/henwen-sip-users-dialplan.conf"'
STAMP=$(date +%Y%m%d-%H%M%S)
BACKUP_DIR="/root/henwen-sipusers-backup-$STAMP"

[ "$(id -u)" = 0 ] || { echo "Run as root (sudo)"; exit 1; }
[ -f "$PJSIP_CONF" ] || { echo "ERROR: $PJSIP_CONF not found"; exit 1; }
[ -f "$EXTENSIONS_CONF" ] || { echo "ERROR: $EXTENSIONS_CONF not found"; exit 1; }

if ! grep -q "HenWen browser transmitter" "$PJSIP_CONF"; then
  echo "ERROR: browser TX is not set up on this box (no HenWen transport in $PJSIP_CONF)."
  echo "Per-user SIP endpoints need its WebSocket transport, modules and Apache proxy."
  echo "Run tx-spike/apply.sh first (Manager > TX Diagnostics > Apply Browser TX Setup)."
  exit 1
fi

echo "== Backing up to $BACKUP_DIR"
mkdir -p "$BACKUP_DIR"
cp -a "$PJSIP_CONF" "$EXTENSIONS_CONF" "$BACKUP_DIR/"
echo "$BACKUP_DIR" > /root/henwen-sipusers-last-backup

# The generated files are written by the HenWen service account, so the
# directory has to be writable by it. It normally already is (ASL3 ships it
# asterisk-owned, and the tap/TX snippets live there), but a hand-built box
# may differ.
echo "== $CUSTOM_DIR"
mkdir -p "$CUSTOM_DIR"
chown asterisk:asterisk "$CUSTOM_DIR"
chmod 755 "$CUSTOM_DIR"

add_include() {   # add_include <file> <line> <what>
  local file="$1" line="$2" what="$3"
  echo "== $file"
  if grep -qF -- "$line" "$file"; then
    echo "   already included, skipping"
    return 0
  fi
  # Ensure the file ends with a newline before appending, or the include
  # would be glued onto the last existing line.
  [ -z "$(tail -c1 "$file")" ] || printf '\n' >> "$file"
  printf '\n; %s: %s -- generated by HenWen from its users table\n; (see sip-users/README.md). Remove with sip-users/rollback.sh.\n%s\n' \
    "$MARKER" "$what" "$line" >> "$file"
  grep -qF -- "$line" "$file" || { echo "   FAILED to add include line"; exit 1; }
  echo "   added: $line"
}
add_include "$PJSIP_CONF" "$PJSIP_LINE" "per-account WebRTC endpoints"
add_include "$EXTENSIONS_CONF" "$DIALPLAN_LINE" "per-account dialplan contexts"

echo "== Reloading PJSIP and the dialplan (live, no restart)"
# `pjsip reload` is not a CLI command on this Asterisk; the config reload for
# pjsip.conf is a module reload of res_pjsip.
asterisk -rx "module reload res_pjsip.so" || echo "   WARN: res_pjsip reload reported an error"
asterisk -rx "dialplan reload" || echo "   WARN: dialplan reload reported an error"

n=$(asterisk -rx "pjsip show endpoints" 2>/dev/null | grep -c "Endpoint:  henwen-u-" || true)
echo "== Done. Per-user endpoints currently loaded: $n"
if [ ! -s "$CUSTOM_DIR/henwen-sip-users.conf" ]; then
  echo "   (none written yet -- HenWen writes $CUSTOM_DIR/henwen-sip-users.conf the"
  echo "    moment an account is given a callsign in Manager > Users)"
fi
